mapper.select:
/* GroupQueryMapper.findGroupList */ SELECT gi.cla_id AS claId, gi.group_nm AS groupNm, gi.school_level AS schoolLevel, gi.grade AS grade, gi.class_number AS classNumber, gi.school_name AS schoolName, gi.school_code AS schoolCode, gi.invite_code AS inviteCode, gi.use_yn AS useYn, gi.created_at AS createdAt, CASE WHEN gi.host_user_no = #{userNo} THEN 'HOST' ELSE 'STUDENT' END AS myRole, gm.status AS myStatus, gm.member_no AS memberNo, (SELECT COUNT(*) FROM group_member gm2 WHERE gm2.group_id = gi.group_id AND gm2.status = 'ACTIVE') AS memberCount FROM group_info gi LEFT JOIN group_member gm ON gm.group_id = gi.group_id AND gm.user_no = #{userNo}
AND gm.status = 'ACTIVE'
WHERE gi.use_yn = 'Y' AND (gi.host_user_no = #{userNo} OR gm.id IS NOT NULL) ORDER BY gi.created_at DESC

/* GroupQueryMapper.countGroupMemberList */
SELECT COUNT(*) FROM group_member
WHERE group_id = #{groupId}

/* GroupQueryMapper.findAdminGroupList */ SELECT gi.group_id AS groupId, gi.cla_id AS claId, gi.group_nm AS groupNm, gi.school_name AS schoolName, CASE WHEN gi.school_level = 'elementary' THEN '초등' WHEN gi.school_level = 'middle' THEN '중등' WHEN gi.school_level = 'high' THEN '고등' ELSE '' END AS schoolLevelNm, gi.grade AS grade, gi.class_number AS classNumber, gi.invite_code AS inviteCode, gi.use_yn AS useYn, gi.created_at AS createdAt, u.sp_user_id AS hostSpUserId, (SELECT COUNT(*) FROM group_member gm WHERE gm.group_id = gi.group_id AND gm.status = 'ACTIVE') AS memberCount FROM group_info gi JOIN `user` u ON u.user_no = gi.host_user_no
AND (gi.group_nm LIKE CONCAT('%', #{keyword}, '%') OR gi.school_name LIKE CONCAT('%', #{keyword}, '%'))
AND gi.school_level = #{schoolLevel}
AND gi.use_yn = #{useYn}
ORDER BY gi.created_at DESC LIMIT #{limit} OFFSET #{offset}

/* GroupQueryMapper.countAdminGroupList */
SELECT COUNT(*)
FROM group_info gi
JOIN `user` u ON u.user_no = gi.host_user_no


        AND (gi.group_nm LIKE CONCAT('%', #{keyword}, '%')
             OR gi.school_name LIKE CONCAT('%', #{keyword}, '%'))


        AND gi.school_level = #{schoolLevel}


        AND gi.use_yn = #{useYn}
